    case 'weekly': return { mode: 'weekly', target: 3 };
    case 'weekly_fixed': return { mode: 'weekly_fixed', days: [1, 3, 5] };
    case 'monthly': return { mode: 'monthly', target: 10 };
    case 'monthly_fixed': return { mode: 'monthly_fixed', dates: [1, 15] };
