import { activeOnly } from '../utils';
// ─── Daily Todo shared logic (used by both Mobile & Web) ──────
import type { PlanItem, PlanItemCheckin, DailyCustomTodo, DailyTodoHistory, PlanItemLink } from '../types';

export interface TodoItemStatus {
  done: boolean;
  autoChecked: boolean;
  linkedModule?: string;
}

/** Build a checkin index grouped by planItemId for a specific date. */
function buildCheckinIndex(checkins: PlanItemCheckin[], date: string): Map<string, PlanItemCheckin> {
  const map = new Map<string, PlanItemCheckin>();
  for (const c of checkins) {
    if (c.date === date && c.done && !c.deleted) {
      map.set(c.planItemId, c);
    }
  }
  return map;
}

export function getTodoItemStatus(
  item: PlanItem,
  checkins: PlanItemCheckin[],
  date: string,
): TodoItemStatus {
  const checkin = checkins.find(
    c => c.planItemId === item.id && c.date === date && c.done && !c.deleted,
  );
  if (!checkin) return { done: false, autoChecked: false };
  return {
    done: true,
    autoChecked: !!checkin.linkedModule,
    linkedModule: checkin.linkedModule,
  };
}

export function getTodoItemStatusMap(
  items: PlanItem[],
  checkins: PlanItemCheckin[],
  date: string,
): Map<string, TodoItemStatus> {
  const index = buildCheckinIndex(checkins, date);
  const map = new Map<string, TodoItemStatus>();
  for (const item of items) {
    const checkin = index.get(item.id);
    if (!checkin) {
      map.set(item.id, { done: false, autoChecked: false });
    } else {
      map.set(item.id, {
        done: true,
        autoChecked: !!checkin.linkedModule,
        linkedModule: checkin.linkedModule,
      });
    }
  }
  return map;
}

